const navToggle=document.querySelector(".nav-toggle"),navOverlay=document.querySelector(".nav-overlay"),body=document.body;if(navToggle&&navOverlay){const e=document.querySelector(".nav-container .nav-menu");if(e){const t=e.cloneNode(!0);navOverlay.appendChild(t)}navToggle.addEventListener("click",()=>{navToggle.classList.toggle("active"),navOverlay.classList.toggle("active"),body.style.overflow=navOverlay.classList.contains("active")?"hidden":""}),navOverlay.querySelectorAll(".nav-link").forEach(e=>{e.addEventListener("click",()=>{navToggle.classList.remove("active"),navOverlay.classList.remove("active"),body.style.overflow=""})})}let resizeTimer;window.addEventListener("resize",()=>{clearTimeout(resizeTimer),resizeTimer=setTimeout(()=>{window.innerWidth>=768&&(navToggle?.classList.remove("active"),navOverlay?.classList.remove("active"),body.style.overflow="")},250)}),document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(e){const t=this.getAttribute("href");if("#"!==t&&""!==t){e.preventDefault();const o=document.querySelector(t);o&&o.scrollIntoView({behavior:"smooth",block:"start"})}})}),console.log("Stanway Designs loaded");